function textEffectPreviewStyle(preset: TextEffectPresetValue): CSSProperties {
  const style: Record<string, string> = {};
  if (preset.startsWith("outline")) {
    const width =
      preset === "outline-thick"
        ? "1.3px"
        : preset === "outline-medium"
          ? "0.9px"
          : "0.5px";
    style["--docs-text-effect-color"] = "#ffffff";
    style["--docs-text-effect-stroke"] = `${width} #176f9c`;
  }
  if (preset.startsWith("shadow")) {
    style["--docs-text-effect-color"] = "#1f5f83";
    style["--docs-text-effect-shadow"] =
      preset === "shadow-offset"
        ? "3px 3px 0 rgba(31, 95, 131, .28)"
        : preset === "shadow-strong"
          ? "2px 2px 2px rgba(15, 23, 42, .45)"
          : "1px 1px 1px rgba(15, 23, 42, .3)";
  }
  if (preset.startsWith("reflection")) {
    style["--docs-text-effect-color"] = "#315f78";
    style["--docs-text-effect-shadow"] = "0 9px 5px rgba(49, 95, 120, .2)";
  }
  if (preset.startsWith("glow")) {
    const color = preset.endsWith("orange")
      ? "234, 88, 12"
      : preset.endsWith("green")
        ? "22, 163, 74"
        : preset.endsWith("purple")
          ? "124, 58, 237"
          : "37, 99, 235";
    style["--docs-text-effect-color"] = `rgb(${color})`;
    style["--docs-text-effect-shadow"] =
      `0 0 4px rgba(${color}, .7), 0 0 8px rgba(${color}, .35)`;
  }
  if (preset === "outline-shadow") {
    style["--docs-text-effect-color"] = "#ffffff";
    style["--docs-text-effect-stroke"] = "0.6px #7c3aed";
    style["--docs-text-effect-shadow"] = "2px 2px 1px rgba(76, 29, 149, .35)";
  }
  return style as CSSProperties;
}

function textEffectPresetIsActive(
  preset: TextEffectPresetValue,
  attrs: TextEffectAttributes,
): boolean {
  const expected = textEffectAttributesForPreset(preset);
  return Boolean(
    expected &&
    expected.outline === attrs.outline &&
    expected.shadow === attrs.shadow &&
    expected.reflection === attrs.reflection &&
    expected.glow === attrs.glow &&
    expected.relief === attrs.relief,
  );
}

