type ParagraphDialogTab = "indents" | "pagination" | "asian";
type ParagraphLineSpacingMode =
  | "default"
  | "single"
  | "oneHalf"
  | "double"
  | "multiple"
  | "atLeast"
  | "exact";
type ParagraphSpecialIndent = "none" | "firstLine" | "hanging";

function paragraphLineSpacingMode(
  lineHeight: string | null,
  lineHeightPt: number | null,
  lineHeightRule: "exact" | "atLeast" | null,
): ParagraphLineSpacingMode {
  if (lineHeightPt !== null && lineHeightRule !== null) return lineHeightRule;
  if (!lineHeight) return "default";
  if (lineHeight === "1") return "single";
  if (lineHeight === "1.5") return "oneHalf";
  if (lineHeight === "2") return "double";
  return "multiple";
}

function paragraphLineSpacingValue(
  mode: ParagraphLineSpacingMode,
  multipleDraft: string,
): string | null {
  if (mode === "default") return null;
  if (mode === "single") return "1";
  if (mode === "oneHalf") return "1.5";
  if (mode === "double") return "2";
  if (mode === "atLeast" || mode === "exact") return null;
  return multipleDraft.trim() || "1.15";
}

function paragraphLineSpacingPreviewValue(
  mode: ParagraphLineSpacingMode,
  valueDraft: string,
): string {
  if (mode === "atLeast" || mode === "exact") {
    const points = normalizeLineHeightPt(valueDraft) ?? 12;
    return `${points}pt`;
  }
  return paragraphLineSpacingValue(mode, valueDraft) ?? "1.15";
}
