function DocumentShapePreview({
  preset,
  fill = "currentColor",
  outline = "currentColor",
  outlineWidthPt = 1.3,
  outlineStyle = "solid",
}: {
  preset: DocumentShapePreset;
  fill?: string;
  outline?: string;
  outlineWidthPt?: number;
  outlineStyle?: "solid" | "dashed" | "dotted";
}) {
  return (
    <PresentationShapePreview
      kind={documentShapeDefinition(preset).previewKind}
      fill={fill}
      stroke={outline}
      strokeWidth={Math.max(0.75, outlineWidthPt * 1.5)}
      strokeStyle={outlineStyle}
      className={homeStyles.documentShapePreview}
    />
  );
}

