/** The review display a PDF showing markup prints (Word's PDF shows the
 * markup the screen shows); asked for the markup, a screen showing none
 * prints All Markup. */
function pdfMarkupView(filter: ReturnType<typeof getTrackedChangeMarkupFilter>): PageExportMarkupView {
  return filter === "none" ? "all" : filter;
}

/** What an intent does with tracked changes, named as Word names it: a Word
 * file keeps them; a PDF or a print shows them (Save as PDF's "Document
 * showing markup", Print Markup) or is the final copy. */
function exportRevisionMessage(intent: ExportIntent) {
  return intent.revisionPolicy === "preserve" && intent.format === "pdf"
    ? "toolbar.exportRevision.showingMarkup"
    : EXPORT_REVISION_MESSAGE[intent.revisionPolicy];
}

