function exportIntentTestId(intent: ExportIntent): string {
  const testId = EXPORT_INTENT_TEST_IDS[intent.id];
  if (!testId) throw new Error(`Missing export action id for ${intent.id}`);
  return testId;
}

/**
 * A command we have not built, with the reason on the item itself.
 *
 * A disabled menu item carries `data-[disabled]:pointer-events-none`, so it is
 * never hovered and a `title` on it never opens — the reason would only exist
 * in the DOM. The reason a command is unavailable is exactly what the reader
 * needs, so it is rendered, and repeated on the accessible label the way
 * `OfficeHomeCommand` repeats its own `disabledReason`.
 */
function UnavailableMenuItemText({
  title,
  reason,
  reasonTestId,
}: {
  title: string;
  reason: string;
  reasonTestId: string;
}) {
  return (
    <span className="note-editor-toolbar-menu__unavailable">
      <span>{title}</span>
      <span
        className="note-editor-toolbar-menu__unavailable-reason"
        data-testid={reasonTestId}
      >
        {reason}
      </span>
    </span>
  );
}

