type RibbonTabId =
  | BaseRibbonTabId
  | PictureContextRibbonTabId
  | EquationContextRibbonTabId
  | ShapeContextRibbonTabId
  | SmartArtContextRibbonTabId
  | ChartContextRibbonTabId
  | HeaderFooterContextRibbonTabId
  | TableContextRibbonTabId;

function officeCommandAccessibleLabel(
  commandLabel: string,
  disabledReason: string | undefined,
): string {
  return disabledReason
    ? `${commandLabel}: ${disabledReason}`
    : commandLabel;
}

const WEB_BASE_RIBBON_TAB_IDS = new Set<BaseRibbonTabId>(["home", "insert"]);

function isBaseRibbonTab(value: unknown): value is BaseRibbonTabId {
  return (
    typeof value === "string" &&
    WEB_BASE_RIBBON_TAB_IDS.has(value as BaseRibbonTabId)
  );
}

function normalizeWebRibbonTab(
  value: unknown,
  tableContextVisible = false,
  pictureContextVisible = false,
  equationContextVisible = false,
  shapeContextVisible = false,
  smartArtContextVisible = false,
  chartContextVisible = false,
  headerFooterContextVisible = false,
  fallbackBaseTab: BaseRibbonTabId = "home",
): RibbonTabId {
  if (isBaseRibbonTab(value)) return value;
  return fallbackBaseTab;
}

