function paragraphOutlineLevelForNode(
  node: ProseMirrorNode,
): TocOutlineLevelValue {
  const direct = normalizeTocOutlineLevel(node.attrs?.tocOutlineLevel);
  if (direct !== null) return direct;
  const structural = Number(node.attrs?.level);
  return node.type.name === "heading" &&
    TOC_OUTLINE_LEVELS.includes(
      structural as (typeof TOC_OUTLINE_LEVELS)[number],
    )
    ? (structural as TocOutlineLevelValue)
    : "none";
}

function selectedParagraphOutlineLevel(
  editor: Editor,
): ParagraphOutlineLevelDraft {
  const { doc, selection } = editor.state;
  const values = new Set<TocOutlineLevelValue>();
  const record = (node: ProseMirrorNode): boolean => {
    if (node.type.name !== "paragraph" && node.type.name !== "heading") {
      return true;
    }
    values.add(paragraphOutlineLevelForNode(node));
    return false;
  };
  if (selection.empty) {
    for (let depth = selection.$from.depth; depth > 0; depth -= 1) {
      if (!record(selection.$from.node(depth))) break;
    }
  } else {
    doc.nodesBetween(selection.from, selection.to, record);
  }
  return values.size === 1 ? [...values][0] : "mixed";
}

