function navigateTrackedChange(
  editor: Editor,
  direction: TrackedChangeNavigationDirection,
): boolean {
  // Among the changes the review shows: Show Markup > Insertions hides the
  
  const target = adjacentTrackedChange(
    getShownTrackedChanges(editor.state),
    editor.state.selection.from,
    direction,
  );
  if (!target) return false;
  // A deleted object (picture, chart, break ...) is selected as the object it is.
  if (target.object) {
    return editor.chain().focus().setNodeSelection(target.from).scrollIntoView().run();
  }
  return editor
    .chain()
    .focus()
    .setTextSelection({ from: target.from, to: target.to })
    .scrollIntoView()
    .run();
}

